  `is_external` tinyint(1) NOT NULL DEFAULT 0 COMMENT 'true = petugas luar (pendeta/pianis luar)',
  `nama_external` varchar(200) DEFAULT NULL COMMENT 'Nama petugas luar jika is_external=true',
  `kategori` enum('insentif','pelayanan') NOT NULL DEFAULT 'insentif',
