/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `kode_akun` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `kode` varchar(30) NOT NULL,
  `parent_kode` varchar(20) DEFAULT NULL,
  `tipe` enum('penerimaan','pengeluaran') NOT NULL,
  `nomor_up` tinyint(4) NOT NULL,
  `nomor_menu` tinyint(4) NOT NULL,
  `nama` varchar(250) NOT NULL,
  `keterangan` text DEFAULT NULL,
  `sumber_lapangan` text DEFAULT NULL,
  `kategori_akun` enum('mph','kategorial') NOT NULL DEFAULT 'mph',
  `aktif` tinyint(1) NOT NULL DEFAULT 1,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `kode_akun_kode_unique` (`kode`),
  KEY `kode_akun_nomor_up_foreign` (`nomor_up`),
  KEY `kode_akun_tipe_nomor_up_index` (`tipe`,`nomor_up`),
  CONSTRAINT `kode_akun_nomor_up_foreign` FOREIGN KEY (`nomor_up`) REFERENCES `unit_pelayanan` (`nomor_up`)
) ENGINE=InnoDB AUTO_INCREMENT=411 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;
