CREATE TABLE `video_ibadah` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `judul` varchar(255) NOT NULL,
  `youtube_url` varchar(255) NOT NULL,
  `tanggal` date NOT NULL,
  `jenis_ibadah` varchar(255) DEFAULT NULL,
  `aktif` tinyint(1) NOT NULL DEFAULT 1,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `warga_jemaat` (
  `id_warga` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `keluarga_id` bigint(20) unsigned DEFAULT NULL,
  `hubungan_keluarga` varchar(30) DEFAULT NULL,
  `nama_lengkap` varchar(255) NOT NULL,
  `no_kk` varchar(30) DEFAULT NULL,
  `lingkungan` varchar(50) DEFAULT NULL,
  `lingkungan_sion_id` bigint(20) unsigned DEFAULT NULL,
  `jenis_kelamin` enum('Laki-laki','Perempuan') DEFAULT NULL,
  `tempat_lahir` varchar(100) DEFAULT NULL,
  `tanggal_lahir` date DEFAULT NULL,
  `golongan_darah` varchar(5) DEFAULT NULL,
  `alamat` text DEFAULT NULL,
  `no_telepon` varchar(20) DEFAULT NULL,
  `email` varchar(255) DEFAULT NULL,
  `pekerjaan` varchar(100) DEFAULT NULL,
  `agama_sebelum` varchar(50) DEFAULT NULL,
  `status_pernikahan` enum('Belum Menikah','Menikah','Cerai','Duda/Janda') DEFAULT NULL,
  `nama_pasangan` varchar(255) DEFAULT NULL,
  `nama_ayah` varchar(255) DEFAULT NULL,
  `nama_ibu` varchar(255) DEFAULT NULL,
  `pasangan_id` bigint(20) unsigned DEFAULT NULL,
  `status_sidi` enum('Sudah Sidi','Belum Sidi') NOT NULL DEFAULT 'Belum Sidi',
  `status_baptis` enum('Sudah Baptis','Belum Baptis') NOT NULL DEFAULT 'Belum Baptis',
  `tanggal_baptis` date DEFAULT NULL,
  `tanggal_sidi` date DEFAULT NULL,
  `is_petugas` tinyint(1) NOT NULL DEFAULT 0,
  `status_jemaat` enum('aktif','pindah','meninggal') NOT NULL DEFAULT 'aktif',
  `jabatan_gereja` varchar(50) DEFAULT NULL COMMENT 'Diakon, Penetua, atau null',
  `tanggal_bergabung` date DEFAULT NULL,
  `foto` varchar(255) DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id_warga`),
  KEY `warga_jemaat_keluarga_id_foreign` (`keluarga_id`),
  KEY `warga_jemaat_lingkungan_sion_id_foreign` (`lingkungan_sion_id`),
  CONSTRAINT `warga_jemaat_keluarga_id_foreign` FOREIGN KEY (`keluarga_id`) REFERENCES `keluarga` (`id`) ON DELETE SET NULL,
  CONSTRAINT `warga_jemaat_lingkungan_sion_id_foreign` FOREIGN KEY (`lingkungan_sion_id`) REFERENCES `lingkungan_sion` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=815 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;
