/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `warta_mingguan` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `minggu_ke` tinyint(4) NOT NULL,
  `bulan` tinyint(4) NOT NULL,
  `tahun` smallint(6) NOT NULL,
  `tanggal_awal` date NOT NULL,
  `tanggal_akhir` date NOT NULL,
  `saldo_awal_minggu` decimal(15,2) NOT NULL DEFAULT 0.00,
  `total_penerimaan` decimal(15,2) NOT NULL DEFAULT 0.00,
  `total_pengeluaran` decimal(15,2) NOT NULL DEFAULT 0.00,
  `saldo_akhir_minggu` decimal(15,2) NOT NULL DEFAULT 0.00,
  `generated_by` bigint(20) unsigned DEFAULT NULL,
  `pdf_path` varchar(255) DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `warta_mingguan_minggu_ke_bulan_tahun_unique` (`minggu_ke`,`bulan`,`tahun`),
  KEY `warta_mingguan_generated_by_foreign` (`generated_by`),
  CONSTRAINT `warta_mingguan_generated_by_foreign` FOREIGN KEY (`generated_by`) REFERENCES `users` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=5 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
